REF = "[ASMT et Transfusion CRS Suisse, Analyses de médecine transfusionnelle chez le patient, version 14 (2026), § 4.2–5.7, 6.3, 7.1, 8.1–8.3, 9.3–9.11 et 10, lu le 28.11.2026]"
HV = "[Swissmedic, Hémovigilance, rapport annuel 2025 (2026), introduction, chap. 3.2.1–3.2.7 et incidents graves, lu le 28.11.2026]"
GAQ = "[Swissmedic, Guide d'assurance-qualité dans la pratique transfusionnelle, édition 2026, chap. 5.1–5.2 et obligations de déclarer, lu le 28.11.2026]"
RHO = "[Compendium.ch, résumé (Brevier) de Rhophylac 300 (immunoglobuline anti-D), posologie des transfusions incompatibles, lu le 28.11.2026 ; AIPS complète à vérifier]"
DAR = "[Compendium.ch, résumé (Brevier) de Darzalex (daratumumab), indication, lu le 28.11.2026 ; AIPS complète à vérifier]"
TOR = "[Tormey et Hendrickson, Transfusion-related red blood cell alloantibodies: induction and consequences, Blood (2019), PMID 30808636, résumé lu le 28.11.2026]"
