_N = [
("def","definition","critère",2,1,REF+" ; "+HV,"L'allo-immunisation post-transfusionnelle désigne l'apparition, après une transfusion de concentrés érythrocytaires (CE), d'allo-anticorps irréguliers dirigés contre des antigènes du donneur (Rh, Kell, Kidd, Duffy, MNS…) ; en Suisse, un allo-anticorps apparu après une transfusion compte comme un effet secondaire de la transfusion et se déclare."),
("epi","epidemiology","chiffre",2,1,HV,"En 2025, Swissmedic a reçu 1506 déclarations d'allo-immunisation, soit 64 % des réactions transfusionnelles déclarées (5,7 pour 1000 transfusions), devant les réactions fébriles non hémolytiques (19 %) ; l'anti-E reste l'allo-anticorps le plus déclaré (354 cas), suivi de l'anti-D (92 cas)."),
("mech","basicSciences","mécanisme",2,0,REF+" ; "+TOR,"Certains allo-anticorps n'apparaissent qu'après plusieurs semaines et d'autres retombent vite sous le seuil de détection (évanescence) ; on estime que seuls 30 % des allo-anticorps induits sont détectés, d'où le risque d'une réponse anamnestique lors d'une nouvelle exposition à l'antigène."),
("hist","anamnesis","contexte suisse",1,1,GAQ,"Les antécédents transfusionnels utiles (allo-anticorps connus, prophylaxie anti-D, réactions passées, maladie qui influence le choix des produits) se transmettent immédiatement et par écrit au laboratoire qui délivre le sang."),
("fem","anamnesis","terrain particulier",2,1,REF,"Chez les filles et les femmes de moins de 50 ans, on transfuse des CE RH1 identiques et, pour une transfusion élective, de phénotype RH/KEL1 compatible, afin de prévenir des allo-anticorps dangereux pour une future grossesse ; une femme RH1 négatif de moins de 50 ans ne doit recevoir à aucun prix des CE RH1 positif."),
("asympt","clinicalExam","signe",1,0,EXP+" ; "+HV,"L'allo-immunisation seule ne donne ni symptôme ni signe : l'examen reste normal et la découverte est biologique, sauf si une hémolyse retardée survient lors d'une nouvelle exposition à l'antigène."),
("redflag","presumptionRedFlags","signe",1,1,REF,"Chez une personne drépanocytaire, une crise vaso-occlusive dans les 28 jours suivant une transfusion, une hausse insuffisante de l'hémoglobine ou une suspicion de réaction transfusionnelle font rechercher activement une allo-immunisation."),
("rai","workupGoldStandard","examen",3,1,REF,"La recherche d'anticorps irréguliers (RAI) se fait en test indirect à l'antiglobuline (IAT) à 37 °C avec des hématies-tests de groupe O ; si elle est positive, on identifie l'anticorps avec au moins deux, idéalement trois hématies-tests porteuses de l'antigène, et l'on confirme l'absence de l'antigène sur les hématies du patient (prudence après une transfusion récente)."),
("tc","workupAlternatives","examen",2,1,REF,"Sans anticorps connu et avec une RAI négative et valide, les CE se libèrent par type and screen (T&S) ; en présence d'un anticorps d'importance clinique, actuel ou ancien, ou d'une identification douteuse, on fait un test de compatibilité (TC, cross-match en IAT) avec chaque CE."),
("dat","workupAlternatives","examen",1,1,REF,"Le test direct à l'antiglobuline (DAT) détecte les anticorps fixés sur les hématies ; on fait une élution lors de chaque réaction transfusionnelle avec des signes d'hémolyse, même si le DAT est négatif."),
("pos","positiveDiagnosis","critère",1,1,REF,"Seuls les allo-anticorps actifs à 37 °C ont une importance transfusionnelle : les anti-M, -N, -Lea, -Leb, -P1 et -A1 qui ne réagissent qu'à froid ou en technique enzymatique ne sont en général pas considérés comme importants, et les anti-Bg ne se recherchent pas."),
("cd38","positiveDiagnosis","diagnostic différentiel",1,1,REF+" ; "+DAR,"Un anticorps monoclonal anti-CD38 (daratumumab, Darzalex, utilisé dans le myélome) peut rendre la RAI positive jusqu'à 6 mois après l'arrêt : on fait avant le traitement deux groupages, une RAI et un phénotype ou génotype étendu, puis on peut délivrer des CE de phénotype compatible."),
("agneg","acuteManagement","décision",3,1,REF,"En présence d'un allo-anticorps d'importance transfusionnelle (Rh, Kell, Kidd, Duffy, anti-S, anti-s), on transfuse des CE dépourvus de l'antigène, typés pour lui et négatifs au test de compatibilité, même si l'anticorps n'est plus détectable."),
("urg","acuteManagement","décision",1,1,REF,"En urgence sans groupe connu, on transfuse des CE de groupe O et du plasma AB, si possible après un premier prélèvement ; la RAI suit aussitôt, on tient toujours compte des anticorps connus, et toute transfusion incompatible relève du médecin responsable de la transfusion."),
("plt","acuteManagement","molécule",1,1,REF+" ; "+RHO,"Après des concentrés plaquettaires RH1 positif chez une fille ou une femme RH1 négatif de moins de 50 ans, on discute au cas par cas une prophylaxie par immunoglobuline anti-D (Rhophylac 300 µg ; transfusion incompatible selon le Brevier : 10 µg pour 0,5 ml de CE ou pour 1 ml de sang transfusé, i.v., max. 3000 µg ; posologies à vérifier dans l'AIPS (Swissmedic)) ; le risque semble plus élevé avec les plaquettes de pool qu'avec celles d'aphérèse."),
("carte","chronicManagement","contexte suisse",3,1,REF+" ; "+HV,"La carte de groupe sanguin porte l'identité, le groupe ABO et RH1 et la spécificité des allo-anticorps identifiés ; elle n'est valable qu'après la deuxième détermination, et sa demande systématique transmet au laboratoire les anticorps découverts dans un autre hôpital."),
("multi","chronicManagement","décision",1,1,REF,"Après un premier allo-anticorps, on prend aussi en compte le phénotype RH/KEL1 ; en présence de plusieurs allo-anticorps, on fait un typage étendu (K, k, Jka, Jkb, Fya, Fyb, S, s) et, chez un patient récemment transfusé, un génotypage."),
("drep","chronicManagement","terrain particulier",2,1,REF,"Chez la personne drépanocytaire, on détermine avant toute transfusion le phénotype et le génotype étendus (avec les variants RHD et RHCE), on respecte à titre préventif RhD, C, E, c, e, K, k, Jka, Jkb, Fya, Fyb, S et s, on fait un test de compatibilité pour chaque CE (pas de libération par T&S) et l'on répète l'identification des anticorps 10 à 21 jours après chaque transfusion."),
("thal","chronicManagement","terrain particulier",1,1,REF,"Chez la personne thalassémique, on transfuse au moins du sang compatible RH/K, puis l'on tient compte du phénotype ou du génotype étendu après une allo-immunisation ou une auto-immunisation."),
("judicious","chronicManagement","prévention",1,1,TOR+" ; "+GAQ,"La transfusion judicieuse reste la principale prévention de l'allo-immunisation ; en Suisse, les indications suivent des directives internes fondées sur les preuves qui intègrent la gestion du sang du patient (PBM)."),
("dhtr","hospitalizationComplications","complication",2,0,TOR+" ; "+REF,"Un allo-anticorps devenu indétectable expose, si l'on transfuse un CE porteur de l'antigène, à une réaction hémolytique retardée ou, plus tard, à une difficulté à trouver du sang compatible : on le respecte à vie."),
("rh1","hospitalizationComplications","complication",2,1,REF+" ; "+HV,"La transfusion de CE RH1 positif à un patient RH1 négatif expose à l'anti-D et constitue un événement grave à déclarer ; en transfusion massive, elle n'est admise, après avis du médecin transfuseur, que chez un homme ou une femme de plus de 50 ans sans anti-D connu, avec retour rapide au RH1 négatif, contrôle au plus tard après 96 heures et dépistage 6 à 12 semaines plus tard."),
("valid","surveillance","seuil",3,1,REF,"L'échantillon prétransfusionnel doit être prélevé au plus 96 heures avant le début de la transfusion ; une RAI négative ne peut valoir 21 jours que sans transfusion dans les 4 mois précédents et hors grossesse, avec une confirmation écrite visée par le médecin, sinon elle ne vaut que 96 heures."),
("postctrl","surveillance","examen",1,1,REF,"Après une transfusion de CE, on recommande une RAI de contrôle, de préférence 6 à 12 semaines plus tard, et l'on en informe idéalement le patient."),
("prono","prognosisDischarge","pronostic",1,1,HV,"L'allo-immunisation est une atteinte irréversible, classée sévère (grade 2) par Swissmedic, car elle limite le choix des produits pour les transfusions futures et peut compliquer une grossesse ; contre un antigène de haute fréquence, du sang compatible peut manquer."),
("preg","prognosisDischarge","terrain particulier",1,0,REF+" ; "+VAU,"Pendant une grossesse, un allo-anticorps d'importance obstétricale s'identifie, se titre régulièrement par la même méthode et conduit à déterminer le phénotype du père ; l'anti-K provoque une anémie fœtale aussi en freinant l'érythropoïèse fœtale, pas seulement par hémolyse."),
("decl","followUpNetwork","contexte suisse",2,1,REF+" ; "+HV,"Tout établissement qui transfuse, hôpital ou cabinet, désigne une personne responsable de l'hémovigilance ; celle-ci ou le médecin transfuseur déclare à Swissmedic les réactions transfusionnelles, dont tout nouvel allo-anticorps post-transfusionnel, les transfusions erronées et les erreurs évitées de justesse (near miss)."),
("lab","followUpNetwork","décision",1,1,REF+" ; "+HV+" ; "+GAQ,"Le médecin signale au laboratoire toute transfusion des 14 derniers jours et lui transmet par écrit les anticorps connus ; sans urgence, on attend les résultats immunohématologiques avant de transfuser."),
]
K = {k: i+1 for i, (k, *_r) in enumerate(_N)}
N = [t[1:] for t in _N]
