      [("P Qualité Sécurité Gestion de l'erreur","On déclare à Swissmedic tout nouvel allo-anticorps, erreur ou near miss."),("F Droit médical suisse","On respecte l'obligation légale de déclarer selon la loi sur les produits thérapeutiques.")],
      (["On prélève un échantillon avant de transfuser si possible.","On tient toujours compte des anticorps connus."],[("d'abord","médecin","Il transfuse des CE O, ou isogroupe si deux groupages sont présents, et du plasma AB si le groupe est inconnu."),("en même temps","laboratoire d'immunohématologie","Il fait aussitôt la RAI et, si besoin, le DAT sur l'échantillon prétransfusionnel."),("ensuite","médecin responsable de la transfusion","Il décide de toute transfusion incompatible et revient dès que possible aux CE compatibles.")]),
      (["On évite toute transfusion non indispensable.","On transmet par écrit les anticorps connus au laboratoire."],[("d'abord","médecin","Il demande une RAI de moins de 96 heures et signale toute transfusion des 14 derniers jours."),("ensuite","laboratoire d'immunohématologie","Il identifie l'anticorps et délivre des CE antigène négatif testés par compatibilité."),("puis","personne responsable de l'hémovigilance","Elle déclare le nouvel anticorps à Swissmedic et fait mettre à jour la carte.")]),
